ROOT=Path(__file__).resolve().parents[2]; HERE=Path(__file__).resolve().parent
BASE='51f2e9a3479a864bf1901aa9c8e3bfa4961bcac0'; NAME='agentic-engineering'
SECTION=re.compile(r'<section\b[^>]*>.*?</section>',re.S)
def esc(s): return html.escape(s,quote=True)
def sha(s): return hashlib.sha256(s.encode()).hexdigest()
def notes(s,t): return re.sub(r'data-speaker-notes="[^"]*"',lambda m:'data-speaker-notes="'+esc(t)+'"',s,count=1)
def patch(s,pattern,value):
 s,n=re.subn(pattern,lambda m:value,s,count=1,flags=re.S); assert n==1,pattern; return s
def bul(items): return '<ul class="bul reveal">'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def cards(items): return '<div class="cards c'+str(len(items))+' reveal">'+''.join('<div class="tile"><h3 class="k">'+a+'</h3><p>'+b+'</p></div>' for a,b in items)+'</div>'
def code(t): return '<div class="code reveal">'+esc(t)+'</div>'
def table(headers,rows): return '<table class="tbl reveal"><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def slide(label,title,content,note,speaker,theme='light',tag='Engineering practice'):
 return f'<section class="slide {theme}" data-label="{esc(label)}" data-speaker-notes="{esc(speaker)}"><div class="slide-content"><div class="slide-head reveal"><span class="snum">0</span><div class="crumb">{tag}</div></div><h2 class="reveal">{title}</h2>{content}<p class="note reveal">{note}</p></div></section>'
original=subprocess.check_output(['git','show',BASE+':'+NAME+'.html'],cwd=ROOT,text=True)
match=re.search(r'(<deck-stage\b[^>]*>)(.*?)(</deck-stage>)',original,re.S)
