def prepare(s,old,new,reference=False):
 s=re.sub(r'(<span class="snum">).*?(</span>)',lambda m:m[1]+str(new)+m[2],s,count=1)
 s=s.replace('<section ',f'<section data-origin-slide="{old}" ',1)
 if reference:
  s=re.sub(r'(<section\b[^>]*>)',lambda m:m[1]+'<div class="reference-banner">Optional reference · <a href="agentic-engineering.html">Back to the talk</a></div>',s,count=1)
 return s
def output(sections,ref=False):
 s=original[:match.start(2)]+'\n\n'+ '\n\n'.join(sections)+'\n\n'+original[match.end(2):]
 s=s.replace('</head>',css+'\n</head>',1)
 s=s.replace('var current = 0, presenter = null, mouseT = null;',"var current = Math.max(0, Array.from(ds.querySelectorAll(':scope > section')).findIndex(function(s){ return s.hasAttribute('data-deck-active'); })), presenter = null, mouseT = null;")
